            aWandererD = aWandererD ^ (((RotL64(aScatter, 53U) + aOrbiterB) + RotL64(aOrbiterK, 51U)) + aTwistWandererUpdateSaltD[((aIndex + 3U)) & S_SALT1]);
            aWandererH = aWandererH + ((RotL64(aIngress, 41U) + aOrbiterI) + RotL64(aOrbiterC, 19U));
            aWandererI = aWandererI ^ ((RotL64(aCross, 3U) + aOrbiterB) + RotL64(aOrbiterH, 27U));
            aWandererK = aWandererK + ((RotL64(aPrevious, 11U) + RotL64(aOrbiterH, 43U)) + aOrbiterF);
            aWandererF = aWandererF ^ ((RotL64(aScatter, 34U) + RotL64(aOrbiterF, 5U)) + aOrbiterJ);
