            aOrbiterC = ((aWandererD + RotL64(aIngress, 50U)) + 0x4CEBEA50E70FDAC0ULL) + aTwistOrbiterAssignSaltA[(((31U - aIndex) + 13U)) & S_SALT1];
            aOrbiterK = ((aWandererA + RotL64(aScatter, 27U)) + 0xB665168323502105ULL) + aTwistOrbiterAssignSaltF[((aIndex + 17U)) & S_SALT1];
            //
            aOrbiterE = ((aOrbiterE + aOrbiterB) + 0x90F44E7AFB6714D3ULL) + aTwistOrbiterUpdateSaltD[((aIndex + 6U)) & S_SALT1];
