            aOrbiterJ = (aOrbiterJ ^ aOrbiterD) ^ 0xD3C075438EA953F1ULL;
            aOrbiterJ = RotL64((aOrbiterJ * 0x6327392E354D65F5ULL), 53U);
            //
            aOrbiterI = ((aOrbiterI + aOrbiterD) + 0x241CF7389061011DULL) + aTwistOrbiterUpdateSaltF[(((31U - aIndex) + 20U)) & S_SALT1];
            aOrbiterC = (aOrbiterC ^ aOrbiterI) ^ 0x872F77153B0B0ED5ULL;
            aOrbiterC = RotL64((aOrbiterC * 0xE54C223DDA872AFBULL), 37U);
            //
            aIngress = aOrbiterE ^ RotL64(aOrbiterB, 27U);
