            aCross ^= (RotL64(pSnowLaneC[((S_BLOCK1 - aIndex + 9079U)) & S_BLOCK1], 11U) ^ RotL64(pSnowLaneA[((S_BLOCK1 - aIndex + 13229U)) & S_BLOCK1], 23U));
            aCross = TwistMix64::DiffuseA(aCross);
            //
            aScatter = (RotL64(aIngress, 5U) ^ RotL64(aCarry, 18U)) ^ (RotL64(aPrevious, 35U) + RotL64(aCross, 47U));
            aScatter = TwistMix64::DiffuseA(aScatter);
            //
            aOrbiterJ = (((aWandererH + RotL64(aScatter, 13U)) + RotL64(aCarry, 23U)) + 0x7DD73AC09BF62093ULL) + aTwistOrbiterAssignSaltD[((aIndex + 13U)) & S_SALT1];
            aOrbiterG = ((aWandererD + RotL64(aIngress, 27U)) + 0x4925674F767BA0EAULL) + aTwistOrbiterAssignSaltB[((aIndex + 24U)) & S_SALT1];
            aOrbiterB = ((aWandererF + RotL64(aPrevious, 37U)) + RotL64(aCarry, 37U)) + 0xB9224663CD8232F3ULL;
            aOrbiterC = ((aWandererG + RotL64(aCross, 53U)) + RotL64(aCarry, 51U)) + 0xC7C88B4F72471FCAULL;
            aOrbiterE = (aWandererJ + RotL64(aScatter, 46U)) + 0x43BBDF5344A9EBC2ULL;
            aOrbiterF = (aWandererE + RotL64(aIngress, 3U)) + 0x931FBCA987F4763DULL;
            aOrbiterD = (aWandererB + RotL64(aPrevious, 21U)) + 0x559C5328B586A86AULL;
            //
            aOrbiterJ = (aOrbiterJ + aOrbiterG) + 0x817775C05B4DF2A8ULL;
            aOrbiterB = (aOrbiterB ^ aOrbiterJ) ^ 0xA4BE04B22D2773BCULL;
            aOrbiterB = RotL64((aOrbiterB * 0x76C63B0F709EEC63ULL), 57U);
            //
            aOrbiterB = ((aOrbiterB + aOrbiterC) + 0x4C87114419AA5CB8ULL) + aTwistOrbiterUpdateSaltF[(((31U - aIndex) + 12U)) & S_SALT1];
            aOrbiterE = ((aOrbiterE ^ aOrbiterB) ^ 0x11C6709A9845CD66ULL) ^ aTwistOrbiterUpdateSaltC[(((31U - aIndex) + 16U)) & S_SALT1];
            aOrbiterE = RotL64((aOrbiterE * 0xE30D9C4C77632D37ULL), 43U);
            //
            aOrbiterG = ((aOrbiterG + aOrbiterF) + 0x7973D05BBE1BF9C1ULL) + aTwistOrbiterUpdateSaltE[((aIndex + 29U)) & S_SALT1];
            aOrbiterC = (aOrbiterC ^ aOrbiterG) ^ 0x57AE0746F57EC5EFULL;
            aOrbiterC = RotL64((aOrbiterC * 0x0CE7659BE5F6C5F5ULL), 11U);
            //
            aOrbiterC = ((aOrbiterC + aOrbiterD) + 0xB2BFA3E412F894A9ULL) + aTwistOrbiterUpdateSaltA[(((31U - aIndex) + 20U)) & S_SALT1];
            aOrbiterJ = (aOrbiterJ ^ aOrbiterC) ^ 0x8167E10A790A277CULL;
            aOrbiterJ = RotL64((aOrbiterJ * 0xCE3A9491D48A32B7ULL), 3U);
            //
            aOrbiterF = (aOrbiterF + aOrbiterB) + 0x6A78B8292C3312B7ULL;
            aOrbiterD = (aOrbiterD ^ aOrbiterF) ^ 0x8F3E99C846471067ULL;
            aOrbiterD = RotL64((aOrbiterD * 0xF2FB3937D4808885ULL), 19U);
            //
            aOrbiterE = (aOrbiterE + aOrbiterJ) + 0xCEFCEBA431E8F7D6ULL;
            aOrbiterF = (aOrbiterF ^ aOrbiterE) ^ 0x4062A5DE57948571ULL;
            aOrbiterF = RotL64((aOrbiterF * 0xBEA763939E63EE4FULL), 51U);
            //
            aOrbiterD = (aOrbiterD + aOrbiterE) + 0x7B682091B69D170FULL;
            aOrbiterG = (aOrbiterG ^ aOrbiterD) ^ 0x5FD9F5F6E43D3C5EULL;
            aOrbiterG = RotL64((aOrbiterG * 0x9B26BD86482BCA57ULL), 29U);
            //
            aIngress = RotL64(aOrbiterJ, 51U) ^ aOrbiterE;
