            aWandererH = aWandererH + (((RotL64(aScatter, 51U) + RotL64(aOrbiterF, 27U)) + aOrbiterD) + aTwistWandererUpdateSaltC[(((31U - aIndex) + 27U)) & S_SALT1]);
            aWandererB = aWandererB ^ ((RotL64(aCross, 27U) + aOrbiterG) + RotL64(aOrbiterJ, 57U));
