            //
            aOrbiterI = ((aWandererE + RotL64(aCross, 53U)) + 0xCADE7A47C609A73EULL) + aTwistOrbiterAssignSaltC[(((31U - aIndex) + 8U)) & S_SALT1];
            aOrbiterA = ((aWandererA + RotL64(aScatter, 43U)) + RotL64(aCarry, 53U)) + 0x928B3A9BFAC369CAULL;
            aOrbiterK = (aWandererC + RotL64(aIngress, 35U)) + 0xE6B668C74074AEF4ULL;
