            aOrbiterF = (((aWandererG + RotL64(aIngress, 13U)) + RotL64(aCarry, 13U)) + 0xB2B3C5E3C2DC8626ULL) + aTwistOrbiterAssignSaltE[((aIndex + 25U)) & S_SALT1];
            aOrbiterJ = (aWandererH + RotL64(aCross, 6U)) + 0x038CCC318AB57A53ULL;
