            //
            aOrbiterF = (aOrbiterF + aOrbiterJ) + 0x1A5A4C323F11A3ACULL;
            aOrbiterG = (aOrbiterG ^ aOrbiterF) ^ 0x3AC526F7B9C57B54ULL;
            aOrbiterG = RotL64((aOrbiterG * 0x0C27C49299BF211FULL), 13U);
            //
            aOrbiterH = (aOrbiterH + aOrbiterF) + 0x647DA5E1975A6518ULL;
            aOrbiterJ = ((aOrbiterJ ^ aOrbiterH) ^ 0x65B0203F07C2A320ULL) ^ aTwistOrbiterUpdateSaltA[(((31U - aIndex) + 18U)) & S_SALT1];
