            //
            aOrbiterC = (((aWandererJ + RotL64(aPrevious, 13U)) + RotL64(aCarry, 29U)) + 0xFE7B8EBBE267B80CULL) + aTwistOrbiterAssignSaltF[((aIndex + 7U)) & S_SALT1];
            aOrbiterB = ((aWandererI + RotL64(aScatter, 5U)) + RotL64(aCarry, 47U)) + 0x9BF9BABD0F3CB618ULL;
            aOrbiterE = ((aWandererA + RotL64(aCross, 27U)) + RotL64(aCarry, 5U)) + 0x185570B3218999CAULL;
