            aOrbiterK = (aWandererD + RotL64(aScatter, 51U)) + 0xF09C379694EA9042ULL;
            aOrbiterD = ((aWandererC + RotL64(aPrevious, 35U)) + 0x46C60D4A98E7D445ULL) + aTwistOrbiterAssignSaltA[((aIndex + 26U)) & S_SALT1];
