            aOrbiterA = (((aWandererA + RotL64(aScatter, 43U)) + RotL64(aCarry, 3U)) + 0x8DDDECA53FA6FDBDULL) + aTwistOrbiterAssignSaltD[(((31U - aIndex) + 24U)) & S_SALT1];
            aOrbiterK = ((aWandererD + RotL64(aPrevious, 5U)) + 0x48231E9E716E76D2ULL) + aTwistOrbiterAssignSaltE[((aIndex + 17U)) & S_SALT1];
            aOrbiterF = ((aWandererB + RotL64(aIngress, 51U)) + RotL64(aCarry, 29U)) + 0xBDCB878A375BD549ULL;
            aOrbiterE = (aWandererJ + RotL64(aCross, 26U)) + 0x5ACB0EA05F2F7C6EULL;
            aOrbiterG = (aWandererE + RotL64(aIngress, 57U)) + 0x2945EEBD7E31816AULL;
