            aCross = (RotL64(aShadowLaneB[((S_BLOCK1 - aIndex + 32384U)) & S_BLOCK1], 11U) ^ RotL64(aMagmaLaneA[((S_BLOCK1 - aIndex + 31133U)) & S_BLOCK1], 57U));
