            aCross = TwistMix64::DiffuseC(aCross);
            //
            aScatter = (RotL64(aPrevious, 22U) ^ RotL64(aCross, 51U)) + (RotL64(aIngress, 37U) ^ RotL64(aCarry, 5U));
            aScatter = TwistMix64::DiffuseC(aScatter);
            //
            aOrbiterA = (aWandererE + RotL64(aIngress, 28U)) + 0x8F11094D051D2B50ULL;
            aOrbiterK = (((aWandererB + RotL64(aScatter, 51U)) + RotL64(aCarry, 39U)) + 0x9C327A84C1E0F38AULL) + aKeyRotateOrbiterAssignSaltD[(((31U - aIndex) + 15U)) & S_SALT1];
            aOrbiterE = (aWandererD + RotL64(aPrevious, 43U)) + 0xC8A51FA80AA65D90ULL;
            aOrbiterC = (aWandererJ + RotL64(aCross, 35U)) + 0x64121D9C72550AEFULL;
            aOrbiterG = ((aWandererA + RotL64(aIngress, 19U)) + RotL64(aCarry, 53U)) + 0xCD6090199E6035CAULL;
            aOrbiterI = ((aWandererI + RotL64(aPrevious, 11U)) + 0xF031038784C45419ULL) + aKeyRotateOrbiterAssignSaltB[(((31U - aIndex) + 23U)) & S_SALT1];
            aOrbiterJ = ((aWandererG + RotL64(aCross, 5U)) + RotL64(aCarry, 23U)) + 0x4602405D5A29C30CULL;
            //
            aOrbiterA = (aOrbiterA + aOrbiterK) + 0xAE31EC4ED8C1ECE1ULL;
            aOrbiterE = ((aOrbiterE ^ aOrbiterA) ^ 0xBDB4E0212A664103ULL) ^ aKeyRotateOrbiterUpdateSaltA[((aIndex + 14U)) & S_SALT1];
            aOrbiterE = RotL64((aOrbiterE * 0x6E0AE51373D4D7B7ULL), 57U);
            //
            aOrbiterC = (aOrbiterC + aOrbiterG) + 0x31826089443C198BULL;
            aOrbiterA = ((aOrbiterA ^ aOrbiterC) ^ 0x42F14D0264E57407ULL) ^ aKeyRotateOrbiterUpdateSaltF[(((31U - aIndex) + 27U)) & S_SALT1];
            aOrbiterA = RotL64((aOrbiterA * 0x061815F72F903B45ULL), 37U);
            //
            aOrbiterG = ((aOrbiterG + aOrbiterA) + 0x4C653284122F7F60ULL) + aKeyRotateOrbiterUpdateSaltB[((aIndex + 16U)) & S_SALT1];
            aOrbiterK = (aOrbiterK ^ aOrbiterG) ^ 0x3CE5B84FB4878D09ULL;
            aOrbiterK = RotL64((aOrbiterK * 0x667C1731A1AA5905ULL), 43U);
            //
            aOrbiterK = (aOrbiterK + aOrbiterE) + 0xE99D96D3DA9E95ABULL;
            aOrbiterI = (aOrbiterI ^ aOrbiterK) ^ 0xA2E77A943BCC8253ULL;
            aOrbiterI = RotL64((aOrbiterI * 0x12B32A34A1191203ULL), 13U);
            //
            aOrbiterI = (aOrbiterI + aOrbiterJ) + 0x89DA1DBA2D575B61ULL;
            aOrbiterC = (aOrbiterC ^ aOrbiterI) ^ 0x69291A35B7956EC7ULL;
            aOrbiterC = RotL64((aOrbiterC * 0xFADC5DAEE8B66CB1ULL), 21U);
            //
            aOrbiterJ = (aOrbiterJ + aOrbiterC) + 0x6F592DAD2AD45849ULL;
            aOrbiterG = (aOrbiterG ^ aOrbiterJ) ^ 0x735C4586A909DCDFULL;
            aOrbiterG = RotL64((aOrbiterG * 0x2396585B1FACBE2BULL), 3U);
            //
            aOrbiterE = ((aOrbiterE + aOrbiterI) + 0xCAE9F52E9073D788ULL) + aKeyRotateOrbiterUpdateSaltE[((aIndex + 29U)) & S_SALT1];
            aOrbiterJ = (aOrbiterJ ^ aOrbiterE) ^ 0xBDB18DDAA4B62951ULL;
            aOrbiterJ = RotL64((aOrbiterJ * 0xD2C874BD9844DF91ULL), 51U);
            //
            aIngress = RotL64(aOrbiterC, 29U) ^ aOrbiterK;
            aIngress = aIngress + (aOrbiterJ ^ RotL64(aOrbiterA, 43U));
            aIngress = aIngress + (aOrbiterG ^ RotL64(aOrbiterI, 35U));
            aIngress = aIngress + RotL64(aOrbiterE, 5U);
