            //
            aWandererD = aWandererD + (((RotL64(aIngress, 11U) + RotL64(aOrbiterK, 35U)) + aOrbiterA) + aKeyRotateWandererUpdateSaltF[(((31U - aIndex) + 25U)) & S_SALT1]);
            aWandererB = aWandererB ^ ((RotL64(aPrevious, 41U) + RotL64(aOrbiterC, 18U)) + aOrbiterG);
            aWandererJ = aWandererJ + (((RotL64(aCross, 23U) + RotL64(aOrbiterJ, 47U)) + aOrbiterE) + RotL64(aCarry, 43U));
            aWandererG = aWandererG ^ ((RotL64(aScatter, 5U) + RotL64(aOrbiterI, 3U)) + aOrbiterC);
            aWandererE = aWandererE + (((RotL64(aPrevious, 57U) + aOrbiterJ) + RotL64(aOrbiterG, 41U)) + RotL64(aCarry, 29U));
            aWandererI = aWandererI ^ ((RotL64(aIngress, 30U) + aOrbiterE) + RotL64(aOrbiterK, 11U));
