            //
            aIngress = (RotL64(aWindLaneA[((aIndex + 5547U)) & S_BLOCK1], 3U) ^ RotL64(aWindLaneB[((aIndex + 581U)) & S_BLOCK1], 21U));
            aIngress ^= (RotL64(aSoilLaneD[((aIndex + 1679U)) & S_BLOCK1], 58U) ^ RotL64(aShadowLaneC[((S_BLOCK1 - aIndex + 5553U)) & S_BLOCK1], 41U));
