            aOrbiterC = (aWandererF + RotL64(aIngress, 37U)) + 0x6025310207B59BDFULL;
            aOrbiterA = ((aWandererA + RotL64(aPrevious, 21U)) + 0x7F10DAB8213E58D7ULL) + aKeyRotateOrbiterAssignSaltF[((aIndex + 24U)) & S_SALT1];
            aOrbiterH = (aWandererB + RotL64(aCross, 29U)) + 0x054C9A9B49EDAAE7ULL;
            aOrbiterF = ((aWandererE + RotL64(aIngress, 34U)) + 0xC04C634914BCEF31ULL) + aKeyRotateOrbiterAssignSaltD[(((31U - aIndex) + 20U)) & S_SALT1];
            aOrbiterD = ((aWandererC + RotL64(aCross, 23U)) + RotL64(aCarry, 47U)) + 0x91106761E9CCD9EFULL;
            aOrbiterK = (aWandererD + RotL64(aScatter, 53U)) + 0x1C9CF8EBB8F505F2ULL;
