            aOrbiterG = ((aWandererK + RotL64(aScatter, 56U)) + RotL64(aCarry, 23U)) + 0x74074DDEDEBF2E4EULL;
            aOrbiterI = (aWandererG + RotL64(aIngress, 13U)) + 0xBFA4C597E519DBB7ULL;
            aOrbiterJ = (aWandererJ + RotL64(aCross, 51U)) + 0x59C618985BB2F530ULL;
