            //
            aOrbiterG = ((aOrbiterG + aOrbiterE) + 0x60AA32ECA9B50286ULL) + aKeyRotateOrbiterUpdateSaltF[((aIndex + 27U)) & S_SALT1];
            aOrbiterI = (aOrbiterI ^ aOrbiterG) ^ 0x6E183FAE1356C27EULL;
