            aOrbiterB = ((aOrbiterB + aOrbiterD) + 0x7446CAC226D33746ULL) + aKeyRotateOrbiterUpdateSaltB[((aIndex + 25U)) & S_SALT1];
            aOrbiterC = (aOrbiterC ^ aOrbiterB) ^ 0xCD19D51C8923FABBULL;
