            aCross = (RotL64(aFuseLaneB[((S_BLOCK1 - aIndex + 27333U)) & S_BLOCK1], 18U) ^ RotL64(aPoisonLaneB[((S_BLOCK1 - aIndex + 26480U)) & S_BLOCK1], 3U));
            aCross ^= (RotL64(aWoodLaneB[((S_BLOCK1 - aIndex + 24656U)) & S_BLOCK1], 41U) ^ RotL64(aShadowLaneD[((S_BLOCK1 - aIndex + 29089U)) & S_BLOCK1], 51U));
