            aOrbiterB = (aWandererC + RotL64(aCross, 53U)) + 0x7C21E59889ED65B1ULL;
            aOrbiterD = (aWandererI + RotL64(aIngress, 30U)) + 0x968609919E7EB481ULL;
            aOrbiterH = (aWandererH + RotL64(aPrevious, 5U)) + 0x934B294D7A1C32EFULL;
