            aOrbiterK = (((aWandererD + RotL64(aPrevious, 57U)) + RotL64(aCarry, 21U)) + 0x9178D63101B3BF6BULL) + aKeyRotateOrbiterAssignSaltF[(((31U - aIndex) + 9U)) & S_SALT1];
            aOrbiterC = ((aWandererJ + RotL64(aCross, 23U)) + 0x3B2A35BFBA83E913ULL) + aKeyRotateOrbiterAssignSaltD[((aIndex + 22U)) & S_SALT1];
