            aOrbiterF = RotL64((aOrbiterF * 0x91D5DE32532A3179ULL), 51U);
            //
            aOrbiterG = (aOrbiterG + aOrbiterE) + 0xA2221E67B46CB7CBULL;
            aOrbiterD = (aOrbiterD ^ aOrbiterG) ^ 0xB9227BBF8744FE8CULL;
            aOrbiterD = RotL64((aOrbiterD * 0xBCAB3842A1C27D23ULL), 23U);
            //
            aOrbiterK = (aOrbiterK + aOrbiterG) + 0x1B9B5E743F8CEDA4ULL;
            aOrbiterB = (aOrbiterB ^ aOrbiterK) ^ 0x8B6FD04208BBE6F6ULL;
            aOrbiterB = RotL64((aOrbiterB * 0x52BF2A45F82AA661ULL), 27U);
            //
            aOrbiterI = (aOrbiterI + aOrbiterC) + 0xC90A732D43385AACULL;
            aOrbiterG = (aOrbiterG ^ aOrbiterI) ^ 0xE38F4AF988B8377AULL;
            aOrbiterG = RotL64((aOrbiterG * 0x7DE7397EFB88B8A7ULL), 11U);
            //
            aOrbiterD = (aOrbiterD + aOrbiterA) + 0x0FAE346858408D13ULL;
            aOrbiterJ = ((aOrbiterJ ^ aOrbiterD) ^ 0x38C3F066677B74A3ULL) ^ aKeyRotateOrbiterUpdateSaltD[((aIndex + 6U)) & S_SALT1];
            aOrbiterJ = RotL64((aOrbiterJ * 0xD35F32A58FD4F9EDULL), 13U);
            //
            aOrbiterJ = ((aOrbiterJ + aOrbiterF) + 0xA538BBD6C8697A3DULL) + aKeyRotateOrbiterUpdateSaltC[(((31U - aIndex) + 13U)) & S_SALT1];
            aOrbiterC = (aOrbiterC ^ aOrbiterJ) ^ 0x6AFC7A911B2D6901ULL;
            aOrbiterC = RotL64((aOrbiterC * 0xF3989B05DC7B3267ULL), 53U);
            //
            aOrbiterE = ((aOrbiterE + aOrbiterB) + 0x80D4F05291B22838ULL) + aKeyRotateOrbiterUpdateSaltA[(((31U - aIndex) + 11U)) & S_SALT1];
            aOrbiterA = ((aOrbiterA ^ aOrbiterE) ^ 0xD7DD57ED76586875ULL) ^ aKeyRotateOrbiterUpdateSaltE[(((31U - aIndex) + 23U)) & S_SALT1];
            aOrbiterA = RotL64((aOrbiterA * 0x4AE309541377D9DBULL), 57U);
            //
            aOrbiterF = (aOrbiterF + aOrbiterI) + 0x5C40584CCD49BF34ULL;
            aOrbiterK = (aOrbiterK ^ aOrbiterF) ^ 0x9177AF336343092DULL;
            aOrbiterK = RotL64((aOrbiterK * 0x3F9D48F04DD6695BULL), 21U);
            //
            aOrbiterC = (aOrbiterC + aOrbiterK) + 0xEEEEBEE61E97D656ULL;
