            aWandererC = aWandererC ^ ((RotL64(aCross, 43U) + RotL64(aOrbiterB, 58U)) + aOrbiterE);
            //
            aCarry = aCarry + (RotL64(aWandererE, 24U) ^ aWandererG);
            aCarry = aCarry + (aWandererC ^ RotL64(aWandererD, 13U));
            aCarry = aCarry + (aWandererI ^ RotL64(aWandererA, 53U));
            aCarry = aCarry + (RotL64(aWandererJ, 47U) ^ aWandererK);
            aCarry = aCarry + (aWandererB ^ RotL64(aWandererH, 21U));
            aCarry = aCarry + RotL64(aWandererF, 41U);
            aCarry = aCarry + RotL64(aIngress, 26U);
            aCarry = TwistMix64::DiffuseA(aCarry);
            //
            aFuseLaneD[S_BLOCK1 - aIndex] = aIngress;
